def luhn_valid(number: str) -> bool:
    if not isinstance(number, str):
        return False

    digits = []
    for char in number:
        if char.isdigit():
            digits.append(int(char))
        elif char.isspace():
            continue
        else:
            return False

    if len(digits) < 2:
        return False

    total = 0
    reverse_digits = digits[::-1]

    for i, d in enumerate(reverse_digits):
        if i % 2 == 1:
            doubled = d * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += d

    return total % 10 == 0
